"use client";

import * as React from "react";
import { CalendarClock, ChevronLeft, ChevronRight, Clock } from "lucide-react";

type DivProps = React.ComponentProps<"div">;
type DivBase = { [key in keyof DivProps as key extends "defaultValue" | "onChange" ? never : key]: DivProps[key] };

export type NaturalDateConfidence = "exact" | "inferred";
export type NaturalDateSource = "text" | "calendar" | "suggestion" | "time";
export type NaturalDateResult = { date: Date; hasTime: boolean; confidence: NaturalDateConfidence };
export type NaturalDateChange = { source: NaturalDateSource; hasTime: boolean; text: string };
export type NaturalTimeOfDay = { hours: number; minutes: number; confidence: NaturalDateConfidence };

export type NaturalLanguageDatePickerProps = DivBase & {
  /** Committed date. All-day values sit at local midnight; `onValueChange` tells you whether a time was given. */
  value?: Date | null;
  defaultValue?: Date | null;
  onValueChange?: (date: Date | null, change: NaturalDateChange) => void;
  /** The text in the field, if you want to drive it ("tomorrow 3pm"). */
  inputValue?: string;
  defaultInputValue?: string;
  onInputValueChange?: (text: string) => void;
  /** Fires with the debounced interpretation of the text (null when nothing is recognised). */
  onParse?: (result: NaturalDateResult | null, text: string) => void;
  /** Clock used for "today", "next fri" and the today marker. Default: the system clock. */
  now?: Date | (() => Date);
  /** Display locale for the chip, the calendar and the time (the grammar itself is English). Default "en-US". */
  locale?: string;
  /** Quick phrases under the field; each is parsed with the same grammar. */
  suggestions?: string[];
  placeholder?: string;
  /** Accessible name of the text field. Default "Date". */
  label?: string;
  /** First column of the calendar: 0 Sunday, 1 Monday. Default 1. */
  weekStartsOn?: 0 | 1;
  minDate?: Date;
  maxDate?: Date;
  /** Show the time row under the calendar. Default true. */
  showTime?: boolean;
  /** Delay before typed text is interpreted, in ms. Default 120. */
  debounce?: number;
  disabled?: boolean;
};

const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const DEBOUNCE_MS = 120;
const FLIP_MS = 200;
const PULSE_MS = 420;
const CHIP_MS = 200;
const MORPH_MS = 240;
const DEFAULT_SUGGESTIONS = ["Today", "Tomorrow", "Next week", "In 2 weeks"];

const WEEKDAYS = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"] as const;
const MONTHS = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"] as const;
const UNITS = ["days", "weeks", "months", "years", "hours", "minutes"] as const;
const PERIODS = ["week", "month", "year", "weekend"] as const;
const RELATIVE_DAYS = ["today", "tomorrow", "yesterday", "tmrw", "tmr"] as const;
const RELATIVE_OFFSETS = [0, 1, -1, 1, 1] as const;
const WORD_TIMES = ["noon", "midday", "midnight", "morning", "afternoon", "evening", "night", "tonight", "eod"] as const;
const WORD_CLOCKS = { noon: [12, "exact"], midday: [12, "exact"], midnight: [0, "exact"], morning: [9, "inferred"], afternoon: [14, "inferred"], evening: [18, "inferred"], night: [19, "inferred"], tonight: [19, "inferred"], eod: [17, "inferred"] } as const;
const UNIT_ALIASES = { d: "days", wk: "weeks", wks: "weeks", mo: "months", mos: "months", yr: "years", yrs: "years", h: "hours", hr: "hours", hrs: "hours", m: "minutes", min: "minutes", mins: "minutes" } as const;
const NUMBER_WORDS = { a: 1, an: 1, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12 } as const;
const FILLER = new Set(["at", "on", "the", "of", "@", "from", "now", "o'clock", "oclock"]);

type Unit = (typeof UNITS)[number];
type DayPart = { date: Date; confidence: NaturalDateConfidence };
type TimeScan = { clock: NaturalTimeOfDay | null; rest: string[]; tonight: boolean };

const pad2 = (value: number) => String(value).padStart(2, "0");
const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());
const addDays = (date: Date, days: number) => new Date(date.getFullYear(), date.getMonth(), date.getDate() + days, date.getHours(), date.getMinutes());
const daysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const monthOf = (date: Date) => ({ year: date.getFullYear(), month: date.getMonth() });
const sameDay = (a: Date, b: Date) => a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
const hasClock = (date: Date | null) => date !== null && (date.getHours() !== 0 || date.getMinutes() !== 0);

function addMonths(date: Date, months: number) {
  const anchor = new Date(date.getFullYear(), date.getMonth() + months, 1);
  const day = Math.min(date.getDate(), daysInMonth(anchor.getFullYear(), anchor.getMonth()));
  return new Date(anchor.getFullYear(), anchor.getMonth(), day, date.getHours(), date.getMinutes());
}

function startOfWeek(date: Date, weekStartsOn: 0 | 1) {
  return addDays(startOfDay(date), -((date.getDay() - weekStartsOn + 7) % 7));
}

/** "2026-11-13" in local time. */
export function dateKey(date: Date) {
  return `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}`;
}

function fromKey(key: string) {
  const [year, month, day] = key.split("-").map(Number);
  return new Date(year ?? 1970, (month ?? 1) - 1, day ?? 1);
}

const dateTimeKey = (date: Date) => `${dateKey(date)}T${pad2(date.getHours())}:${pad2(date.getMinutes())}`;

/** Exact match first, then the single word the token is a prefix of (once the token is `min` letters long). */
function matchWord(token: string, words: readonly string[], min: number) {
  const exact = words.indexOf(token);
  if (exact >= 0) return exact;
  if (token.length < min) return -1;
  let found = -1;
  for (let index = 0; index < words.length; index += 1) {
    const word = words[index];
    if (word !== undefined && word.startsWith(token)) {
      if (found >= 0) return -1;
      found = index;
    }
  }
  return found;
}

function matchPeriod(token: string) {
  const candidates = PERIODS.filter((period) => period === token || period.startsWith(token));
  if (candidates.length === 0) return null;
  return candidates.reduce((shortest, period) => (period.length < shortest.length ? period : shortest));
}

function matchUnit(token: string): Unit | null {
  const alias = (UNIT_ALIASES as { [key: string]: Unit | undefined })[token];
  if (alias) return alias;
  const index = matchWord(token, UNITS, 1);
  return index >= 0 ? UNITS[index] ?? null : null;
}

function parseCount(token: string) {
  if (/^\d{1,3}$/.test(token)) return Number(token);
  return (NUMBER_WORDS as { [key: string]: number | undefined })[token] ?? null;
}

function clockFrom(hourText: string, minuteText: string | undefined, meridiem: string | undefined): NaturalTimeOfDay | null {
  const hours = Number(hourText);
  const minutes = minuteText === undefined ? 0 : Number(minuteText);
  if (!Number.isInteger(hours) || minutes < 0 || minutes > 59) return null;
  if (meridiem) {
    if (hours < 1 || hours > 12) return null;
    return { hours: (hours % 12) + (meridiem.startsWith("p") ? 12 : 0), minutes, confidence: "exact" };
  }
  if (hours > 23) return null;
  return { hours, minutes, confidence: "exact" };
}

/** A bare hour after a date ("fri 3", "tomorrow at 9"): 7–11 read as morning, 12 and 1–6 as afternoon, 13–23 as given. */
function inferredHour(hour: number): NaturalTimeOfDay {
  const hours = hour === 0 || hour >= 12 ? hour : hour >= 7 ? hour : hour + 12;
  return { hours, minutes: 0, confidence: "inferred" };
}

function scanTime(tokens: string[]): TimeScan | null {
  let explicit: NaturalTimeOfDay | null = null;
  let word: NaturalTimeOfDay | null = null;
  let tonight = false;
  const rest: string[] = [];
  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index] ?? "";
    const next = tokens[index + 1];
    const attached = /^(\d{1,2})(?::(\d{2}))?(am|pm|a|p)$/.exec(token);
    if (attached) {
      const clock = clockFrom(attached[1] ?? "", attached[2], attached[3]);
      if (!clock || explicit) return null;
      explicit = clock;
      continue;
    }
    const numeric = /^(\d{1,2})(?::(\d{2}))?$/.exec(token);
    if (numeric && next !== undefined && /^(am|pm)$/.test(next)) {
      const clock = clockFrom(numeric[1] ?? "", numeric[2], next);
      if (!clock || explicit) return null;
      explicit = clock;
      index += 1;
      continue;
    }
    if (numeric && numeric[2] !== undefined) {
      const clock = clockFrom(numeric[1] ?? "", numeric[2], undefined);
      if (!clock || explicit) return null;
      explicit = clock;
      continue;
    }
    const partial = /^(\d{1,2}):(\d)?$/.exec(token);
    if (partial && Number(partial[1]) <= 23) {
      if (explicit) return null;
      explicit = { ...inferredHour(Number(partial[1])), minutes: Number(partial[2] ?? 0) * 10 };
      continue;
    }
    if (token === "end" && next === "of" && tokens[index + 2] === "day") {
      word = { hours: 17, minutes: 0, confidence: "inferred" };
      index += 2;
      continue;
    }
    if (token === "after" && tokens[index - 1] === "day") {
      rest.push(token);
      continue;
    }
    const wordIndex = matchWord(token, WORD_TIMES, 3);
    if (wordIndex >= 0) {
      const name = WORD_TIMES[wordIndex] ?? "noon";
      const [hours, confidence] = WORD_CLOCKS[name];
      word = { hours, minutes: 0, confidence };
      if (name === "tonight") tonight = true;
      continue;
    }
    rest.push(token);
  }
  return { clock: explicit ?? word, rest, tonight };
}

const KEYWORDS = [...FILLER, "next", "this", "in", "day", "after", "weekend", "now", ...WEEKDAYS, ...MONTHS, ...UNITS, ...WORD_TIMES, ...RELATIVE_DAYS];

/** A one- or two-letter start of a known word ("dec 1 a|t", "tomorrow mo|rning") is still being typed, not a mistake. */
function unfinished(token: string) {
  return token.length <= 2 && /^[a-z]+$/.test(token) && KEYWORDS.some((keyword) => keyword.startsWith(token));
}

function numericDate(token: string, today: Date): DayPart | null {
  const iso = /^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/.exec(token);
  if (iso) {
    const year = Number(iso[1]);
    const month = Number(iso[2]) - 1;
    const day = Number(iso[3]);
    if (month < 0 || month > 11 || day < 1 || day > daysInMonth(year, month)) return null;
    return { date: new Date(year, month, day), confidence: "exact" };
  }
  const full = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(token);
  if (full) {
    const month = Number(full[1]) - 1;
    const day = Number(full[2]);
    const year = Number(full[3]);
    if (month < 0 || month > 11 || day < 1 || day > daysInMonth(year, month)) return null;
    return { date: new Date(year, month, day), confidence: "exact" };
  }
  const short = /^(\d{1,2})\/(\d{1,2})$/.exec(token);
  if (short) return monthDay(Number(short[1]) - 1, Number(short[2]), today);
  return null;
}

/** Month + day without a year: this year, unless the day is more than a week in the past, then next year. */
function monthDay(month: number, day: number, today: Date): DayPart | null {
  if (month < 0 || month > 11 || day < 1 || day > 31) return null;
  const grace = addDays(today, -7).getTime();
  for (const year of [today.getFullYear(), today.getFullYear() + 1]) {
    if (day > daysInMonth(year, month)) continue;
    const candidate = new Date(year, month, day);
    if (candidate.getTime() >= grace) return { date: candidate, confidence: "inferred" };
  }
  return null;
}

function monthDayForm(tokens: string[], today: Date): DayPart | null {
  let month = -1;
  const numbers: string[] = [];
  for (const token of tokens) {
    if (/^\d/.test(token)) {
      numbers.push(token);
      continue;
    }
    const monthIndex = matchWord(token, MONTHS, 3);
    if (monthIndex >= 0 && month < 0) {
      month = monthIndex;
      continue;
    }
    if (matchWord(token, WEEKDAYS, 2) >= 0 && month >= 0) continue;
    if (matchWord(token, WEEKDAYS, 2) >= 0) continue;
    return null;
  }
  if (month < 0 || numbers.length === 0 || numbers.length > 2) return null;
  let day = -1;
  let year = -1;
  for (const token of numbers) {
    const dayMatch = /^(\d{1,2})(?:st|nd|rd|th)?$/.exec(token);
    if (dayMatch && day < 0) day = Number(dayMatch[1]);
    else if (/^\d{4}$/.test(token) && year < 0) year = Number(token);
    else return null;
  }
  if (day < 1) return null;
  if (year < 0) return monthDay(month, day, today);
  if (day > daysInMonth(year, month)) return null;
  return { date: new Date(year, month, day), confidence: "exact" };
}

function resolveDay(tokens: string[], today: Date): DayPart | null {
  const first = tokens[0];
  if (first === undefined) return null;
  if (tokens.length === 1) {
    const relative = matchWord(first, RELATIVE_DAYS, 3);
    if (relative >= 0) return { date: addDays(today, RELATIVE_OFFSETS[relative] ?? 0), confidence: "exact" };
    const weekday = matchWord(first, WEEKDAYS, 2);
    if (weekday >= 0) return { date: addDays(today, (weekday - today.getDay() + 7) % 7), confidence: "inferred" };
    if (first === "weekend") return { date: addDays(today, (6 - today.getDay() + 7) % 7), confidence: "inferred" };
    const numeric = numericDate(first, today);
    if (numeric) return numeric;
    const ordinal = /^(\d{1,2})(?:st|nd|rd|th)$/.exec(first);
    if (ordinal) {
      const day = Number(ordinal[1]);
      const thisMonth = day <= daysInMonth(today.getFullYear(), today.getMonth()) ? new Date(today.getFullYear(), today.getMonth(), day) : null;
      if (thisMonth && thisMonth.getTime() >= today.getTime()) return { date: thisMonth, confidence: "inferred" };
      const next = addMonths(startOfDay(new Date(today.getFullYear(), today.getMonth(), 1)), 1);
      if (day > daysInMonth(next.getFullYear(), next.getMonth())) return null;
      return { date: new Date(next.getFullYear(), next.getMonth(), day), confidence: "inferred" };
    }
    return null;
  }
  if (tokens.length === 3 && first === "day" && tokens[1] === "after" && matchWord(tokens[2] ?? "", ["tomorrow"], 3) === 0) {
    return { date: addDays(today, 2), confidence: "exact" };
  }
  if (tokens.length === 2 && (first === "next" || first === "this")) {
    const target = tokens[1] ?? "";
    const weekday = matchWord(target, WEEKDAYS, 1);
    if (weekday >= 0) {
      const ahead = (weekday - today.getDay() + 7) % 7;
      return { date: addDays(today, first === "next" && ahead === 0 ? 7 : ahead), confidence: "inferred" };
    }
    const period = matchPeriod(target);
    if (period === "weekend") {
      const saturday = addDays(today, (6 - today.getDay() + 7) % 7);
      return { date: first === "next" ? addDays(saturday, 7) : saturday, confidence: "inferred" };
    }
    if (first !== "next" || period === null) return null;
    if (period === "week") return { date: addDays(today, 7), confidence: "inferred" };
    if (period === "month") return { date: addMonths(today, 1), confidence: "inferred" };
    return { date: addMonths(today, 12), confidence: "inferred" };
  }
  const offset = first === "in" ? 1 : 0;
  if (tokens.length === offset + 2) {
    const count = parseCount(tokens[offset] ?? "");
    const unit = matchUnit(tokens[offset + 1] ?? "");
    if (count !== null && unit !== null) {
      if (unit === "days") return { date: addDays(today, count), confidence: "exact" };
      if (unit === "weeks") return { date: addDays(today, count * 7), confidence: "exact" };
      if (unit === "months") return { date: addMonths(today, count), confidence: "exact" };
      if (unit === "years") return { date: addMonths(today, count * 12), confidence: "exact" };
      return null;
    }
  }
  return monthDayForm(tokens, today);
}

/**
 * Reads a small English grammar: today · tomorrow · yesterday · tonight · next/this <weekday> · <weekday> · next week/month/year ·
 * this/next weekend · in N days/weeks/months/years/hours/minutes · <month> <day>[ <year>] · <day> <month> · YYYY-MM-DD · MM/DD[/YYYY] ·
 * the 21st · 3pm · 3:30 pm · 15:00 · noon · midnight · morning (9) · afternoon (14) · evening (18) · eod (17) · now, in any combination
 * ("next fri 3pm", "dec 1 at 9:30", "tomorrow morning"). Weekday, month and unit names may be abbreviated to an unambiguous prefix.
 * Dates are local; all-day results sit at midnight. `confidence` is "inferred" when the parser had to choose a day, a year or a
 * meridiem for you (weekdays, missing years, "morning", a bare hour) and "exact" otherwise. Returns null when nothing is recognised.
 */
export function parseNaturalDate(text: string, now: Date = new Date()): NaturalDateResult | null {
  const normalized = text.toLowerCase().replace(/(\d{4}-\d{2}-\d{2})t(\d)/g, "$1 $2").replace(/[,·]/g, " ").replace(/\s+/g, " ").trim();
  if (!normalized) return null;
  if (normalized === "now") {
    return { date: new Date(now.getFullYear(), now.getMonth(), now.getDate(), now.getHours(), now.getMinutes()), hasTime: true, confidence: "exact" };
  }
  const scanned = scanTime(normalized.split(" ").filter((token) => !FILLER.has(token)));
  if (!scanned) return null;
  const { clock, rest, tonight } = scanned;
  const today = startOfDay(now);
  const offset = rest[0] === "in" ? 1 : 0;
  if (rest.length === offset + 2) {
    const count = parseCount(rest[offset] ?? "");
    const unit = matchUnit(rest[offset + 1] ?? "");
    if (count !== null && (unit === "hours" || unit === "minutes")) {
      if (clock) return null;
      const hours = now.getHours() + (unit === "hours" ? count : 0);
      const minutes = now.getMinutes() + (unit === "minutes" ? count : 0);
      return { date: new Date(now.getFullYear(), now.getMonth(), now.getDate(), hours, minutes), hasTime: true, confidence: "exact" };
    }
  }
  const dayTokens = tonight && rest.length === 0 ? ["today"] : rest;
  let day = resolveDay(dayTokens, today);
  let finalClock = clock;
  if (!day && dayTokens.length >= 2) {
    const last = dayTokens[dayTokens.length - 1] ?? "";
    const head = dayTokens.slice(0, -1);
    if (!finalClock && /^\d{1,2}$/.test(last) && Number(last) <= 23) {
      const without = resolveDay(head, today);
      if (without) {
        day = without;
        finalClock = inferredHour(Number(last));
      }
    } else if (unfinished(last)) {
      const without = resolveDay(head, today);
      if (without) day = { date: without.date, confidence: "inferred" };
    }
  }
  if (!day) {
    if (dayTokens.length > 0 || !finalClock) return null;
    const base = new Date(today.getFullYear(), today.getMonth(), today.getDate(), finalClock.hours, finalClock.minutes);
    return { date: base.getTime() <= now.getTime() ? addDays(base, 1) : base, hasTime: true, confidence: "inferred" };
  }
  if (!finalClock) return { date: day.date, hasTime: false, confidence: day.confidence };
  const date = new Date(day.date.getFullYear(), day.date.getMonth(), day.date.getDate(), finalClock.hours, finalClock.minutes);
  return { date, hasTime: true, confidence: day.confidence === "exact" && finalClock.confidence === "exact" ? "exact" : "inferred" };
}

/** "3pm" · "3:30 pm" · "15:00" · "noon" · "9" (a bare hour follows the same morning/afternoon rule as the full grammar). */
export function parseTimeOfDay(text: string): NaturalTimeOfDay | null {
  const tokens = text.toLowerCase().replace(/\s+/g, " ").trim().split(" ").filter((token) => token !== "" && !FILLER.has(token));
  if (tokens.length === 0) return null;
  const scanned = scanTime(tokens);
  if (!scanned) return null;
  if (scanned.rest.length === 0) return scanned.clock;
  const only = scanned.rest[0] ?? "";
  if (!scanned.clock && scanned.rest.length === 1 && /^\d{1,2}$/.test(only) && Number(only) <= 23) return inferredHour(Number(only));
  return null;
}

/** "3:00 PM" (narrow no-break spaces from Intl are replaced with plain spaces). */
export function formatTimeOfDay(date: Date, locale = "en-US") {
  return new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit" }).format(date).replace(/[  ]/g, " ");
}

/** "Fri, Nov 13" · "Fri, Nov 13 · 3:00 PM" · "Thu, Jan 8, 2027" (the year appears when it is not the current one). */
export function formatNaturalDate(date: Date, hasTime: boolean, now: Date = new Date(), locale = "en-US") {
  const withYear = date.getFullYear() !== now.getFullYear();
  const day = new Intl.DateTimeFormat(locale, { weekday: "short", month: "short", day: "numeric", ...(withYear ? { year: "numeric" } : {}) }).format(date);
  return hasTime ? `${day} · ${formatTimeOfDay(date, locale)}` : day;
}

function sameResult(a: NaturalDateResult | null, b: NaturalDateResult | null) {
  if (a === null || b === null) return a === b;
  return a.date.getTime() === b.date.getTime() && a.hasTime === b.hasTime && a.confidence === b.confidence;
}

function monthGrid(year: number, month: number, weekStartsOn: 0 | 1) {
  const lead = (new Date(year, month, 1).getDay() - weekStartsOn + 7) % 7;
  const weeks: Date[][] = [];
  for (let row = 0; row < 6; row += 1) {
    const week: Date[] = [];
    for (let column = 0; column < 7; column += 1) week.push(new Date(year, month, 1 - lead + row * 7 + column));
    weeks.push(week);
  }
  return weeks;
}

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(true);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

function animatable(node: Element | null, reduced: boolean): node is HTMLElement {
  return !!node && !reduced && typeof (node as HTMLElement).animate === "function";
}

export function NaturalLanguageDatePicker({
  value: valueProp,
  defaultValue = null,
  onValueChange,
  inputValue: inputProp,
  defaultInputValue,
  onInputValueChange,
  onParse,
  now,
  locale = "en-US",
  suggestions = DEFAULT_SUGGESTIONS,
  placeholder = "tomorrow 3pm, next fri, in 2 weeks…",
  label = "Date",
  weekStartsOn = 1,
  minDate,
  maxDate,
  showTime = true,
  debounce = DEBOUNCE_MS,
  disabled = false,
  className = "",
  ref,
  ...rest
}: NaturalLanguageDatePickerProps) {
  const reduced = useReducedMotion();
  const baseId = React.useId();
  const chipId = `${baseId}-chip`;
  const gridId = `${baseId}-grid`;
  const monthId = `${baseId}-month`;
  const inputId = `${baseId}-input`;
  const timeId = `${baseId}-time`;

  const nowRef = React.useRef(now);
  nowRef.current = now;
  const onParseRef = React.useRef(onParse);
  onParseRef.current = onParse;
  const readNow = React.useCallback(() => {
    const source = nowRef.current;
    return typeof source === "function" ? source() : source ?? new Date();
  }, []);

  const [localValue, setLocalValue] = React.useState(defaultValue);
  const value = valueProp === undefined ? localValue : valueProp;
  const [valueHasTime, setValueHasTime] = React.useState(() => hasClock(valueProp === undefined ? defaultValue : valueProp));
  const [localText, setLocalText] = React.useState(() => {
    if (defaultInputValue !== undefined) return defaultInputValue;
    const initial = valueProp === undefined ? defaultValue : valueProp;
    return initial ? formatNaturalDate(initial, hasClock(initial), readNow(), locale) : "";
  });
  const text = inputProp === undefined ? localText : inputProp;
  const [preview, setPreview] = React.useState(() => parseNaturalDate(text, readNow()));
  const [month, setMonth] = React.useState(() => monthOf(value ?? preview?.date ?? readNow()));
  const [focusKey, setFocusKey] = React.useState(() => dateKey(value ?? preview?.date ?? readNow()));
  const [ghost, setGhost] = React.useState(null as string | null);
  const [timeText, setTimeText] = React.useState("");
  const [editingTime, setEditingTime] = React.useState(false);

  const rootRef = React.useRef(null as HTMLDivElement | null);
  const inputRef = React.useRef(null as HTMLInputElement | null);
  const chipRef = React.useRef(null as HTMLSpanElement | null);
  const ghostRef = React.useRef(null as HTMLSpanElement | null);
  const gridRef = React.useRef(null as HTMLDivElement | null);
  const previewRef = React.useRef(preview);
  const committed = React.useRef(value ? value.getTime() : null);
  const pendingFocus = React.useRef(null as string | null);
  const ghostToken = React.useRef(0);
  const pulsed = React.useRef(null as string | null);
  const filled = React.useRef(value ? dateKey(value) : null);
  const chipWas = React.useRef(false);
  const monthWas = React.useRef(`${month.year}-${pad2(month.month + 1)}`);

  const today = startOfDay(readNow());
  const monthKey = `${month.year}-${pad2(month.month + 1)}`;
  const outOfRange = (date: Date) => {
    const day = startOfDay(date).getTime();
    return (minDate !== undefined && day < startOfDay(minDate).getTime()) || (maxDate !== undefined && day > startOfDay(maxDate).getTime());
  };
  const previewShown = preview !== null && !(value !== null && preview.date.getTime() === value.getTime() && preview.hasTime === valueHasTime);
  const previewKey = previewShown ? dateKey(preview.date) : null;
  const valueKey = value ? dateKey(value) : null;
  const chipText = previewShown ? formatNaturalDate(preview.date, preview.hasTime, readNow(), locale) : "";
  const previewBlocked = previewShown && outOfRange(preview.date);
  const displayTime = previewShown ? (preview.hasTime ? formatTimeOfDay(preview.date, locale) : "") : value && valueHasTime ? formatTimeOfDay(value, locale) : "";

  const setText = (next: string) => {
    if (inputProp === undefined) setLocalText(next);
    onInputValueChange?.(next);
  };

  const replacePreview = (result: NaturalDateResult | null) => {
    previewRef.current = result;
    setPreview(result);
  };

  const commit = (next: Date | null, hasTime: boolean, source: NaturalDateSource, textOverride?: string) => {
    const nextText = textOverride ?? (next ? formatNaturalDate(next, hasTime, readNow(), locale) : "");
    if (next && previewShown && !reduced) setGhost(formatNaturalDate(next, hasTime, readNow(), locale));
    committed.current = next ? next.getTime() : null;
    if (valueProp === undefined) setLocalValue(next);
    setValueHasTime(hasTime);
    setText(nextText);
    replacePreview(next ? { date: next, hasTime, confidence: "exact" } : null);
    if (next) {
      setMonth(monthOf(next));
      setFocusKey(dateKey(next));
    }
    onValueChange?.(next, { source, hasTime, text: nextText });
  };

  // Debounced interpretation of the text: the chip and the calendar follow only after a pause, so nothing flashes mid-word.
  React.useEffect(() => {
    const run = () => {
      const result = parseNaturalDate(text, readNow());
      if (sameResult(result, previewRef.current)) return;
      previewRef.current = result;
      setPreview(result);
      onParseRef.current?.(result, text);
    };
    if (text.trim() === "") {
      run();
      return;
    }
    const id = window.setTimeout(run, debounce);
    return () => window.clearTimeout(id);
  }, [text, debounce, readNow]);

  // A value set by the host (not through this component) is reflected in the field, the calendar and the time row.
  React.useEffect(() => {
    const time = value ? value.getTime() : null;
    if (committed.current === time) return;
    committed.current = time;
    const hasTime = hasClock(value);
    setValueHasTime(hasTime);
    setText(value ? formatNaturalDate(value, hasTime, readNow(), locale) : "");
    replacePreview(value ? { date: value, hasTime, confidence: "exact" } : null);
    if (value) {
      setMonth(monthOf(value));
      setFocusKey(dateKey(value));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  // The calendar turns to the month of the interpreted date.
  React.useLayoutEffect(() => {
    if (!previewShown) return;
    const target = monthOf(preview.date);
    if (target.year !== month.year || target.month !== month.month) setMonth(target);
    setFocusKey(dateKey(preview.date));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [previewKey]);

  // Page flip: the new month slides in from the side it comes from (forward = from the right).
  React.useLayoutEffect(() => {
    const from = monthWas.current;
    monthWas.current = monthKey;
    if (from === monthKey) return;
    const direction = monthKey > from ? 1 : -1;
    if (rootRef.current) rootRef.current.dataset.direction = direction > 0 ? "forward" : "backward";
    const grid = gridRef.current;
    if (!animatable(grid, reduced)) return;
    grid.animate([{ transform: `translateX(${direction * 24}px)`, opacity: 0 }, { transform: "translateX(0)", opacity: 1 }], { duration: FLIP_MS, easing: EASE });
  }, [monthKey, reduced]);

  // The interpreted day pulses once when it changes (after the month it lives in is on screen).
  React.useLayoutEffect(() => {
    if (!previewKey) {
      pulsed.current = null;
      return;
    }
    if (pulsed.current === previewKey) return;
    const button = gridRef.current?.querySelector(`[data-date="${previewKey}"]:not([data-outside])`) ?? null;
    if (!(button instanceof HTMLElement)) return;
    pulsed.current = previewKey;
    if (!animatable(button, reduced)) return;
    button.animate([{ transform: "scale(1)" }, { transform: "scale(1.18)", offset: 0.45 }, { transform: "scale(1)" }], { duration: PULSE_MS, easing: EASE });
  }, [previewKey, monthKey, reduced]);

  // The committed day settles: the filled circle scales in.
  React.useLayoutEffect(() => {
    if (filled.current === valueKey) return;
    const button = valueKey ? gridRef.current?.querySelector(`[data-date="${valueKey}"]:not([data-outside])`) ?? null : null;
    if (valueKey && !(button instanceof HTMLElement)) return;
    filled.current = valueKey;
    if (!animatable(button, reduced)) return;
    button.animate([{ transform: "scale(0.8)" }, { transform: "scale(1)" }], { duration: 260, easing: EASE });
  }, [valueKey, monthKey, reduced]);

  // The chip rises in when an interpretation appears; later changes only swap its text.
  React.useLayoutEffect(() => {
    const was = chipWas.current;
    chipWas.current = previewShown;
    if (!previewShown || was) return;
    const chip = chipRef.current;
    if (!animatable(chip, reduced)) return;
    chip.animate([{ opacity: 0, transform: "translateY(4px)" }, { opacity: 1, transform: "translateY(0)" }], { duration: CHIP_MS, easing: EASE });
  }, [previewShown, reduced]);

  // On confirm a copy of the chip travels up into the field while the field's text fades in.
  React.useLayoutEffect(() => {
    if (ghost === null) return;
    const node = ghostRef.current;
    const input = inputRef.current;
    const token = ++ghostToken.current;
    const finish = () => { if (token === ghostToken.current) setGhost(null); };
    if (!node || !input || !animatable(node, reduced)) {
      finish();
      return;
    }
    const from = node.getBoundingClientRect();
    const to = input.getBoundingClientRect();
    const dx = to.left + 36 - from.left;
    const dy = to.top + to.height / 2 - (from.top + from.height / 2);
    const animation = node.animate(
      [{ transform: "translate(0px, 0px) scale(1)", opacity: 1 }, { transform: `translate(${dx}px, ${dy}px) scale(0.9)`, opacity: 0 }],
      { duration: MORPH_MS, easing: "cubic-bezier(0.4, 0, 0.2, 1)", fill: "forwards" },
    );
    animation.onfinish = finish;
    input.animate([{ color: "transparent" }, { color: "transparent", offset: 0.6 }, { color: "var(--color-foreground)" }], { duration: MORPH_MS + 120, easing: "ease-out" });
    return () => animation.cancel();
  }, [ghost, reduced]);

  React.useLayoutEffect(() => {
    const key = pendingFocus.current;
    if (!key) return;
    const button = gridRef.current?.querySelector(`[data-date="${key}"]:not([data-outside])`) ?? null;
    if (button instanceof HTMLElement) {
      pendingFocus.current = null;
      button.focus({ preventScroll: true });
    }
  });

  React.useEffect(() => {
    if (!editingTime) setTimeText(displayTime);
  }, [displayTime, editingTime]);

  const confirmText = () => {
    if (text.trim() === "") {
      if (value !== null) commit(null, false, "text");
      return;
    }
    const result = parseNaturalDate(text, readNow());
    if (!result || outOfRange(result.date)) {
      replacePreview(result);
      return;
    }
    if (value !== null && result.date.getTime() === value.getTime() && result.hasTime === valueHasTime) {
      setText(formatNaturalDate(result.date, result.hasTime, readNow(), locale));
      replacePreview({ date: result.date, hasTime: result.hasTime, confidence: "exact" });
      return;
    }
    commit(result.date, result.hasTime, "text");
  };

  const onInputKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "Enter") {
      event.preventDefault();
      if (event.nativeEvent.isComposing) return;
      confirmText();
      return;
    }
    if (event.key === "Escape" && text !== "") {
      event.preventDefault();
      setText("");
      replacePreview(null);
      onParseRef.current?.(null, "");
    }
  };

  const selectDay = (day: Date, source: NaturalDateSource) => {
    if (disabled || outOfRange(day)) return;
    const clock = previewShown && preview.hasTime ? preview.date : value && valueHasTime ? value : null;
    const next = clock ? new Date(day.getFullYear(), day.getMonth(), day.getDate(), clock.getHours(), clock.getMinutes()) : startOfDay(day);
    commit(next, clock !== null, source);
  };

  const applySuggestion = (phrase: string) => {
    const result = parseNaturalDate(phrase, readNow());
    if (!result || outOfRange(result.date)) {
      setText(phrase);
      inputRef.current?.focus({ preventScroll: true });
      return;
    }
    commit(result.date, result.hasTime, "suggestion", phrase);
  };

  const shiftMonth = (delta: number) => {
    setMonth((current) => monthOf(new Date(current.year, current.month + delta, 1)));
  };

  const onGridKeyDown = (event: React.KeyboardEvent) => {
    const target = event.target;
    if (!(target instanceof HTMLElement) || !target.dataset.date) return;
    const current = fromKey(target.dataset.date);
    let next: Date | null = null;
    switch (event.key) {
      case "ArrowLeft": next = addDays(current, -1); break;
      case "ArrowRight": next = addDays(current, 1); break;
      case "ArrowUp": next = addDays(current, -7); break;
      case "ArrowDown": next = addDays(current, 7); break;
      case "Home": next = startOfWeek(current, weekStartsOn); break;
      case "End": next = addDays(startOfWeek(current, weekStartsOn), 6); break;
      case "PageUp": next = addMonths(current, event.shiftKey ? -12 : -1); break;
      case "PageDown": next = addMonths(current, event.shiftKey ? 12 : 1); break;
      case "Enter":
      case " ":
        event.preventDefault();
        selectDay(current, "calendar");
        return;
      default:
        return;
    }
    event.preventDefault();
    const key = dateKey(next);
    pendingFocus.current = key;
    setFocusKey(key);
    setMonth(monthOf(next));
  };

  const commitTime = () => {
    if (!editingTime) return;
    setEditingTime(false);
    const target = value ?? (previewShown ? preview.date : null);
    const trimmed = timeText.trim();
    if (!target) {
      setTimeText(displayTime);
      return;
    }
    if (trimmed === "") {
      if (value && valueHasTime) commit(startOfDay(value), false, "time");
      else setTimeText(displayTime);
      return;
    }
    const clock = parseTimeOfDay(trimmed);
    if (!clock) {
      setTimeText(displayTime);
      return;
    }
    const next = new Date(target.getFullYear(), target.getMonth(), target.getDate(), clock.hours, clock.minutes);
    if (value && valueHasTime && next.getTime() === value.getTime()) {
      setTimeText(displayTime);
      return;
    }
    commit(next, true, "time");
  };

  const weeks = monthGrid(month.year, month.month, weekStartsOn);
  const inMonth = (key: string | null) => key !== null && key.startsWith(monthKey);
  const todayKey = dateKey(today);
  const tabbableKey = inMonth(focusKey) ? focusKey : inMonth(previewKey) ? previewKey : inMonth(valueKey) ? valueKey : inMonth(todayKey) ? todayKey : `${monthKey}-01`;
  const monthLabel = new Intl.DateTimeFormat(locale, { month: "long", year: "numeric" }).format(new Date(month.year, month.month, 1));
  const weekdayLabels = Array.from({ length: 7 }, (_, index) => {
    const date = new Date(2026, 10, 1 + ((weekStartsOn + index) % 7));
    return { short: new Intl.DateTimeFormat(locale, { weekday: "short" }).format(date).slice(0, 2), long: new Intl.DateTimeFormat(locale, { weekday: "long" }).format(date) };
  });
  const dayLabel = new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric", year: "numeric" });

  return (
    <div
      {...rest}
      ref={(node) => {
        rootRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      data-slot="natural-language-date-picker"
      data-value={value ? dateTimeKey(value) : ""}
      data-has-time={valueHasTime ? "true" : "false"}
      data-preview={previewShown ? dateTimeKey(preview.date) : ""}
      data-preview-time={previewShown && preview.hasTime ? "true" : "false"}
      data-confidence={previewShown ? preview.confidence : undefined}
      data-recognized={text.trim() === "" ? undefined : preview ? "true" : "false"}
      data-month={monthKey}
      data-disabled={disabled ? "true" : undefined}
      className={`w-full max-w-[400px] rounded-2xl bg-card p-3 text-card-foreground shadow-sm ring-1 ring-border ${className}`}
    >
      <div className="relative">
        <CalendarClock aria-hidden="true" strokeWidth={1.75} className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
        <input
          ref={inputRef}
          id={inputId}
          data-input
          type="text"
          value={text}
          placeholder={placeholder}
          disabled={disabled}
          aria-label={label}
          aria-describedby={chipId}
          aria-controls={gridId}
          autoComplete="off"
          autoCapitalize="off"
          autoCorrect="off"
          spellCheck={false}
          enterKeyHint="done"
          onChange={(event) => setText(event.target.value)}
          onKeyDown={onInputKeyDown}
          className="h-10 w-full rounded-xl border border-border bg-background pl-9 pr-3 text-sm text-foreground outline-none transition-[border-color,box-shadow] duration-200 motion-reduce:transition-none placeholder:text-muted-foreground/70 focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/40 disabled:cursor-default disabled:opacity-50"
        />
      </div>

      <div data-chip-row className="relative mt-2 flex h-7 items-center">
        <span
          ref={chipRef}
          id={chipId}
          role="status"
          aria-live="polite"
          data-chip
          data-state={previewShown ? "visible" : "hidden"}
          data-blocked={previewBlocked ? "true" : undefined}
          className={`inline-flex h-7 max-w-full items-center rounded-full px-2.5 text-xs font-medium tabular-nums ${previewShown ? "" : "invisible"} ${previewBlocked ? "bg-muted text-muted-foreground line-through" : "bg-chart-1/12 text-foreground"}`}
        >
          <span data-chip-text className="truncate">{chipText}</span>
        </span>
        {ghost !== null && (
          <span ref={ghostRef} data-chip-ghost aria-hidden="true" className="pointer-events-none absolute left-0 top-0 inline-flex h-7 items-center rounded-full bg-chart-1/12 px-2.5 text-xs font-medium tabular-nums text-foreground will-change-transform">
            {ghost}
          </span>
        )}
      </div>

      {suggestions.length > 0 && (
        <div role="group" aria-label="Quick dates" data-suggestions className="mt-2 flex flex-wrap gap-1.5">
          {suggestions.map((phrase) => (
            <button
              key={phrase}
              type="button"
              data-suggestion={phrase}
              disabled={disabled}
              onClick={() => applySuggestion(phrase)}
              className="inline-flex h-7 items-center rounded-full border border-border bg-background px-2.5 text-xs text-muted-foreground outline-none transition-colors duration-150 motion-reduce:transition-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-default disabled:opacity-50"
            >
              {phrase}
            </button>
          ))}
        </div>
      )}

      <div data-calendar className="mt-3">
        <div className="flex items-center justify-between pl-1">
          <span id={monthId} data-month-label aria-live="polite" className="text-sm font-medium">{monthLabel}</span>
          <div className="flex items-center gap-0.5">
            <button type="button" data-nav="prev" aria-label="Previous month" disabled={disabled} onClick={() => shiftMonth(-1)} className="inline-flex size-7 items-center justify-center rounded-md text-muted-foreground outline-none transition-colors duration-150 motion-reduce:transition-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50">
              <ChevronLeft aria-hidden="true" className="size-4" />
            </button>
            <button type="button" data-nav="next" aria-label="Next month" disabled={disabled} onClick={() => shiftMonth(1)} className="inline-flex size-7 items-center justify-center rounded-md text-muted-foreground outline-none transition-colors duration-150 motion-reduce:transition-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50">
              <ChevronRight aria-hidden="true" className="size-4" />
            </button>
          </div>
        </div>
        <div key={monthKey} ref={gridRef} data-grid data-month={monthKey} className="mt-1 will-change-transform">
          <table id={gridId} role="grid" aria-labelledby={monthId} onKeyDown={onGridKeyDown} className="w-full table-fixed border-collapse">
            <thead>
              <tr>
                {weekdayLabels.map((weekday) => (
                  <th key={weekday.long} scope="col" abbr={weekday.long} className="h-6 text-[11px] font-normal text-muted-foreground">{weekday.short}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {weeks.map((week, row) => (
                <tr key={row}>
                  {week.map((day) => {
                    const key = dateKey(day);
                    const outside = day.getMonth() !== month.month;
                    const selected = !outside && key === valueKey;
                    const isPreview = !outside && key === previewKey;
                    const isToday = sameDay(day, today);
                    const blocked = outOfRange(day) || disabled;
                    return (
                      <td key={key} role="gridcell" aria-selected={selected} className="h-9 p-0 text-center">
                        <button
                          type="button"
                          data-date={key}
                          data-outside={outside ? "true" : undefined}
                          data-today={isToday ? "true" : undefined}
                          data-selected={selected ? "true" : undefined}
                          data-preview={isPreview ? "true" : undefined}
                          tabIndex={!outside && key === tabbableKey ? 0 : -1}
                          disabled={blocked}
                          aria-label={dayLabel.format(day)}
                          aria-current={isToday ? "date" : undefined}
                          onClick={() => selectDay(day, "calendar")}
                          className={`relative mx-auto flex size-8 items-center justify-center rounded-full text-[13px] tabular-nums outline-none transition-colors duration-150 will-change-transform motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-card disabled:cursor-default ${
                            selected ? "bg-primary font-medium text-primary-foreground" : outside ? "text-muted-foreground/40 hover:bg-muted" : "text-foreground hover:bg-muted"
                          } ${isPreview ? "ring-2 ring-chart-1 ring-offset-1 ring-offset-card" : ""} ${blocked ? "opacity-35 hover:bg-transparent" : ""}`}
                        >
                          <span>{day.getDate()}</span>
                          {isToday && <span data-today-dot aria-hidden="true" className="absolute bottom-[3px] left-1/2 size-1 -translate-x-1/2 rounded-full bg-current opacity-70" />}
                        </button>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showTime && (
        <div data-time-row data-has-time={displayTime !== "" ? "true" : "false"} className="mt-2 flex h-9 items-center gap-2 rounded-xl bg-muted/60 pl-2.5 pr-1">
          <Clock aria-hidden="true" strokeWidth={1.75} className="size-3.5 shrink-0 text-muted-foreground" />
          <label htmlFor={timeId} className="text-xs text-muted-foreground">Time</label>
          <input
            id={timeId}
            data-time-input
            type="text"
            value={timeText}
            placeholder="All day"
            disabled={disabled || (value === null && !previewShown)}
            autoComplete="off"
            spellCheck={false}
            enterKeyHint="done"
            onFocus={() => setEditingTime(true)}
            onChange={(event) => {
              setEditingTime(true);
              setTimeText(event.target.value);
            }}
            onBlur={commitTime}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                commitTime();
              } else if (event.key === "Escape") {
                event.preventDefault();
                setTimeText(displayTime);
                setEditingTime(false);
                event.currentTarget.blur();
              }
            }}
            className="ml-auto h-7 w-28 rounded-md bg-transparent px-2 text-right text-sm tabular-nums text-foreground outline-none transition-colors duration-150 motion-reduce:transition-none placeholder:text-muted-foreground/70 focus-visible:bg-background focus-visible:ring-2 focus-visible:ring-ring/40 disabled:cursor-default disabled:opacity-60"
          />
        </div>
      )}
    </div>
  );
}

